/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);

    const dp = new Map();
    let answer = 0n;

    for (const value of arr) {
        let ways = 1n;

        for (const left of arr) {
            if (left >= value) break;
            if (value % left !== 0) continue;

            const right = value / left;
            if (dp.has(right)) {
                ways = (ways + dp.get(left) * dp.get(right)) % MOD;
            }
        }

        dp.set(value, ways);
        answer = (answer + ways) % MOD;
    }

    return Number(answer);
};
