/**
 * @param {number} n
 * @return {number}
 */
var clumsy = function(n) {
    let total = 0;
    let current = n;

    for (let i = n - 1, step = 0; i >= 1; i--, step++) {
        const op = step % 4;

        if (op === 0) {
            current *= i;
        } else if (op === 1) {
            current = current >= 0
                ? Math.floor(current / i)
                : -Math.floor(-current / i);
        } else if (op === 2) {
            total += current;
            current = i;
        } else {
            total += current;
            current = -i;
        }
    }

    return total + current;
};
