var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.maxValue = 100000;
    this.maxBit = 131072;

    this.countBIT = new Int32Array(this.maxValue + 1);
    this.sumBIT = new Float64Array(this.maxValue + 1);

    this.queue = [];
    this.head = 0;
    this.size = 0;
    this.totalSum = 0;
};

MKAverage.prototype._update = function(value, delta) {
    for (let i = value; i <= this.maxValue; i += i & -i) {
        this.countBIT[i] += delta;
        this.sumBIT[i] += delta * value;
    }
};

MKAverage.prototype._sumFirst = function(count) {
    let index = 0;
    let accumulatedCount = 0;
    let accumulatedSum = 0;

    for (let step = this.maxBit; step > 0; step >>= 1) {
        const next = index + step;
        if (
            next <= this.maxValue &&
            accumulatedCount + this.countBIT[next] < count
        ) {
            index = next;
            accumulatedCount += this.countBIT[next];
            accumulatedSum += this.sumBIT[next];
        }
    }

    const value = index + 1;
    return accumulatedSum + (count - accumulatedCount) * value;
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this._update(num, 1);
    this.totalSum += num;
    this.size++;

    if (this.size > this.m) {
        const removed = this.queue[this.head++];
        this._update(removed, -1);
        this.totalSum -= removed;
        this.size--;
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.size < this.m) {
        return -1;
    }

    const smallestK = this._sumFirst(this.k);
    const smallestMMinusK = this._sumFirst(this.m - this.k);
    const middleSum = smallestMMinusK - smallestK;

    return Math.floor(middleSum / (this.m - 2 * this.k));
};
