 */
var maxScore = function(nums) {
    const m = nums.length;
    const totalMasks = 1 << m;
    const memo = new Array(totalMasks).fill(-1);
    const pairCount = new Array(totalMasks).fill(0);

    for (let mask = 1; mask < totalMasks; mask++) {
        pairCount[mask] = pairCount[mask >> 1] + (mask & 1);
    }

    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    function dfs(mask) {
        if (mask === totalMasks - 1) return 0;
        if (memo[mask] !== -1) return memo[mask];

        const operation = pairCount[mask] / 2 + 1;
        let best = 0;

        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;

            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;

                const nextMask = mask | (1 << i) | (1 << j);
                const score = operation * gcd(nums[i], nums[j]) + dfs(nextMask);
                if (score > best) best = score;
