var maximumANDSum = function(nums, numSlots) {
    const totalPositions = 2 * numSlots;
    const totalMasks = 1 << totalPositions;
    const dp = new Float64Array(totalMasks);
    const bitCount = new Uint8Array(totalMasks);

    dp.fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dp[mask] < 0) continue;

        const used = bitCount[mask];
        if (used === nums.length) continue;

        const value = nums[used];

        for (let pos = 0; pos < totalPositions; pos++) {
            const bit = 1 << pos;
            if ((mask & bit) !== 0) continue;

            const nextMask = mask | bit;
            const slot = Math.floor(pos / 2) + 1;
            const score = dp[mask] + (value & slot);

            if (score > dp[nextMask]) {
                dp[nextMask] = score;
            }

            bitCount[nextMask] = used + 1;
        }
    }

    let answer = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (bitCount[mask] === nums.length && dp[mask] > answer) {
            answer = dp[mask];
        }
    }

    return answer;
};
