 * @return {number}
 */
var numOfWays = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;

    const modPow = (base, exponent) => {
        let result = 1n;
        while (exponent > 0n) {
            if (exponent & 1n) result = result * base % MOD;
            base = base * base % MOD;
            exponent >>= 1n;
        }
        return result;
    };

    const factorial = Array(n + 1).fill(1n);
    const inverseFactorial = Array(n + 1).fill(1n);

    for (let i = 1; i <= n; i++) {
        factorial[i] = factorial[i - 1] * BigInt(i) % MOD;
    }

    inverseFactorial[n] = modPow(factorial[n], MOD - 2n);
    for (let i = n; i >= 1; i--) {
        inverseFactorial[i - 1] = inverseFactorial[i] * BigInt(i) % MOD;
    }

    const combination = (total, choose) => {
        return factorial[total] *
            inverseFactorial[choose] % MOD *
            inverseFactorial[total - choose] % MOD;
    };

    const countWays = (arr) => {
        if (arr.length <= 2) return 1n;

        const root = arr[0];
        const left = [];
        const right = [];

        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < root) {
                left.push(arr[i]);
            } else {
                right.push(arr[i]);
            }
        }

        const leftWays = countWays(left);
        const rightWays = countWays(right);
        const interleavings = combination(
            left.length + right.length,
            left.length
        );

        return interleavings * leftWays % MOD * rightWays % MOD;
    };

    const result = (countWays(nums) - 1n + MOD) % MOD;
    return Number(result);
};
