/**
 * @param {number} n
 * @param {number[][]} restrictions
 * @param {number[][]} requests
 * @return {boolean[]}
 */
var friendRequests = function(n, restrictions, requests) {
    const parent = Array.from({ length: n }, (_, i) => i);
    const rank = Array(n).fill(0);

    function find(x) {
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    function union(a, b) {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (rank[rootA] < rank[rootB]) {
            [rootA, rootB] = [rootB, rootA];
        }

        parent[rootB] = rootA;
        if (rank[rootA] === rank[rootB]) {
            rank[rootA]++;
        }
    }

    const result = [];

    for (const [u, v] of requests) {
        const rootU = find(u);
        const rootV = find(v);

        let allowed = true;

        if (rootU !== rootV) {
            for (const [x, y] of restrictions) {
                const rootX = find(x);
                const rootY = find(y);

                if (
                    (rootX === rootU && rootY === rootV) ||
                    (rootX === rootV && rootY === rootU)
                ) {
                    allowed = false;
                    break;
                }
            }

            if (allowed) {
                union(rootU, rootV);
            }
        }

        result.push(allowed);
    }

    return result;
};
