/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();

    function solve(size, a, b) {
        if (a + b === size + 1) {
            return [1, 1];
        }

        const key = `${size},${a},${b}`;
        if (memo.has(key)) {
            return memo.get(key);
        }

        const fixedWinners = [];
        const ordinaryPairs = [];

        if (size % 2 === 1) {
            fixedWinners.push((size + 1) / 2);
        }

        for (let left = 1; left <= Math.floor(size / 2); left++) {
            const right = size + 1 - left;

            if (left === a || right === a) {
                fixedWinners.push(a);
            } else if (left === b || right === b) {
                fixedWinners.push(b);
            } else {
                ordinaryPairs.push([left, right]);
            }
        }

        let baseA = 0;
        let baseB = 0;

        for (const winner of fixedWinners) {
            if (winner < a) baseA++;
            if (winner < b) baseB++;
        }

        const nextStates = new Set();
        const combinations = 1 << ordinaryPairs.length;

        for (let mask = 0; mask < combinations; mask++) {
            let countA = baseA;
            let countB = baseB;

            for (let i = 0; i < ordinaryPairs.length; i++) {
                const winner = (mask & (1 << i))
                    ? ordinaryPairs[i][1]
                    : ordinaryPairs[i][0];

                if (winner < a) countA++;
                if (winner < b) countB++;
            }

            nextStates.add(`${countA + 1},${countB + 1}`);
        }

        const nextSize = Math.ceil(size / 2);
        let earliest = Infinity;
        let latest = 0;

        for (const state of nextStates) {
            const [nextA, nextB] = state.split(',').map(Number);
            const [currentEarliest, currentLatest] =
                solve(nextSize, nextA, nextB);

            earliest = Math.min(earliest, currentEarliest + 1);
            latest = Math.max(latest, currentLatest + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    }

    return solve(n, firstPlayer, secondPlayer);
};
