 * @param {number[]} nums
 * @param {number[][]} edges
 * @return {number[]}
 */
var getCoprimes = function(nums, edges) {
    const n = nums.length;
    const graph = Array.from({ length: n }, () => []);

    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const coprime = Array.from({ length: 51 }, () => Array(51).fill(false));

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    for (let a = 1; a <= 50; a++) {
        for (let b = 1; b <= 50; b++) {
            coprime[a][b] = gcd(a, b) === 1;
        }
    }

    const answer = Array(n).fill(-1);
    const depth = Array(n).fill(0);
    const paths = Array.from({ length: 51 }, () => []);

    const stack = [[0, -1, 0]];

    while (stack.length > 0) {
        const [node, parent, state] = stack.pop();

        if (state === 0) {
            let best = -1;
            let bestDepth = -1;

            for (let value = 1; value <= 50; value++) {
                if (coprime[nums[node]][value] && paths[value].length > 0) {
                    const ancestor = paths[value][paths[value].length - 1];
                    if (depth[ancestor] > bestDepth) {
                        bestDepth = depth[ancestor];
                        best = ancestor;
                    }
                }
            }

            answer[node] = best;
            paths[nums[node]].push(node);

            stack.push([node, parent, 1]);

            for (const neighbor of graph[node]) {
                if (neighbor !== parent) {
                    depth[neighbor] = depth[node] + 1;
                    stack.push([neighbor, node, 0]);
                }
            }
        } else {
            paths[nums[node]].pop();
        }
    }

    return answer;
};
